            var pl = (ds && ds.plHistory && ds.plHistory.length) ? ds.plHistory[ds.plHistory.length - 1] : 0;
            var ph = (ds && ds.patientsHistory) || [];
            var pat = ph.length ? (ph[ph.length - 1] || 0) : 0;
            var totPat = ph.reduce(function(a, b) { return a + (b || 0); }, 0);
            return this._idxFrom(pl, pat, totPat);
        }
        // v1.2.0: the top band also needs the access floor. A month above +500 that serves
        // fewer than ACCESS_FLOOR visits is profitable but below the access floor and scores
        // in the middle band, so a maximum patient tariff is no longer free.
        _idxFrom(pl, pat, totPat) {
            if (pl > 500) return pat >= this.ACCESS_FLOOR ? 3 : 2;
            if (pl >= -1000) return 2;
            if (totPat === 0) return 0;
            return 1;
        }
        _lowAccess(pl, pat) { return pl > 500 && pat < this.ACCESS_FLOOR; }
        // 0–3 verdict rescaled to the 0–100 grade the server reads. Preserves the
        // original tier ordering/relative values (0/33/67/100).
        _composite(ds) { return this._cl(Math.round(this._scoreIdx(ds) / 3 * 100)); }
        _tier(pct) {
            if (pct >= 80) return 'expert';
            if (pct >= 60) return 'senior';
            if (pct >= 40) return 'junior';
            return 'beginner';
        }
        _grade(pct) {
            if (pct >= 80) return 'A';
            if (pct >= 60) return 'B';
            if (pct >= 40) return 'C';
            return 'D';
        }
        _gradeKey(idx) {
            return ['grade_withdrawal', 'grade_unsustainable', 'grade_subsidized', 'grade_sustainable'][idx] || 'grade_unsustainable';
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    urbanAnnualProfit: 1660000,
                    ruralInvestment: 0,
                    monthlyPL: 0,
                    patientsServed: 0,
                    currentTariff: 30,
                    currentModel: '',
                    fixedCosts: 15000,
                    varCost: 25,
                    projectedVisits: 0,
                    abandoned: false,
                    lastAnalysis: '',
                    plHistory: [],
                    investmentHistory: [],
                    patientsHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    tariff: 30,
                    model: 'C',
                    crisisResponse: 'abandon',
                    additionalBudget: 30,
                    sustainableStructure: 'community',
                    finalTariff: 15
                };
            }
            this._updateBriefing(state);
        }

        _getConversion(tariff) {
            if (tariff <= 15) return 0.70;
            if (tariff <= 30) return 0.70 - (tariff - 15) * 0.03;
            if (tariff <= 40) return 0.25 - (tariff - 30) * 0.015;
            return 0.10;
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var titleEl = document.getElementById('briefingTitle');
            if (titleEl && window.mySimulation) {
                titleEl.textContent = window.mySimulation.t(round.titleKey);
            }
            var textEl = document.getElementById('briefingText');
            if (textEl && window.mySimulation) {
                textEl.innerHTML = window.mySimulation.t(round.briefKey);
            }

            var panels = ['round1Controls', 'round2Controls', 'round3Controls', 'round4Controls'];
            for (var i = 0; i < panels.length; i++) {
                var panel = document.getElementById(panels[i]);
                if (panel) {
                    panel.style.display = panels[i] === round.controls ? 'block' : 'none';
                }
            }

            var analysisPanel = document.getElementById('analysisPanel');
            var analysisTextEl = document.getElementById('analysisText');
            if (analysisPanel && analysisTextEl && state.domainState && state.domainState.lastAnalysis) {
                analysisPanel.style.display = 'block';
                analysisTextEl.innerHTML = state.domainState.lastAnalysis;
            }

            var plEl = document.getElementById('monthlyPLDisplay');
            if (plEl && state.domainState) {
                var plVal = state.domainState.monthlyPL || 0;
                plEl.style.color = plVal >= 0 ? '#2d8659' : '#c0392b';
            }

            if (idx === 0) {
                var self = this;
                var tariffInput = document.getElementById('tariffInput');
                if (tariffInput && !tariffInput._listenerAdded) {
                    tariffInput.addEventListener('input', function() {
                        var t = parseFloat(this.value) || 30;
                        var conv = self._getConversion(t);
                        var vis = Math.round(1800 * conv);
                        var margin = t - 25;
                        var be = margin > 0 ? Math.ceil(15000 / margin) : 99999;
                        var projDiv = document.getElementById('demandProjection');
                        if (projDiv) {
                            projDiv.innerHTML = self._t('proj_r1', {
                                conv: Math.round(conv * 100),
                                visits: vis,
                                be: be.toLocaleString(),
                                gapColor: (vis >= be ? '#2d8659' : '#c0392b'),
                                gap: (vis - be).toLocaleString()
                            });
                        }
                    });
                    tariffInput._listenerAdded = true;
                    tariffInput.dispatchEvent(new Event('input'));
                }
            }

            if (idx === 1) {
                var self2 = this;
                var modelSel = document.getElementById('modelSelect');
                var tariffIn2 = document.getElementById('tariffInput2');
                var updateR2 = function() {
                    var m = modelSel ? modelSel.value : 'C';
                    var t2 = tariffIn2 ? (parseFloat(tariffIn2.value) || 20) : 20;
                    var fc, vc, cap;
                    if (m === 'A' || m === 'B') { fc = 15000; vc = 25; cap = 3000; }
                    else if (m === 'C') { fc = 8000; vc = 12; cap = 1500; }
                    else { fc = 5000; vc = 12; cap = 800; }
                    var conv2 = self2._getConversion(t2);
                    var vis2 = Math.min(Math.round(1800 * conv2), cap);
                    var mgn = t2 - vc;
                    var be2 = mgn > 0 ? Math.ceil(fc / mgn) : 99999;
                    var pl2 = vis2 * t2 - vis2 * vc - fc;
                    var projDiv2 = document.getElementById('modelProjection');
                    if (projDiv2) {
                        projDiv2.innerHTML = self2._t('proj_r2', {
                            model: m,
                            fc: fc.toLocaleString(),
                            vc: vc,
                            cap: cap.toLocaleString(),
                            visits: vis2,
                            be: be2.toLocaleString(),
                            plColor: (pl2 >= 0 ? '#2d8659' : '#c0392b'),
                            pl: Math.round(pl2).toLocaleString()
                        });
                    }
                };
                if (modelSel && !modelSel._listenerAdded2) {
                    modelSel.addEventListener('change', updateR2);
                    modelSel._listenerAdded2 = true;
                }
                if (tariffIn2 && !tariffIn2._listenerAdded2) {
                    tariffIn2.addEventListener('input', updateR2);
                    tariffIn2._listenerAdded2 = true;
                }
                updateR2();
            }

            if (idx === 2) {
                var crisisSelect = document.getElementById('crisisSelect');
                if (crisisSelect && !crisisSelect._listenerAdded) {
                    crisisSelect.addEventListener('change', function() {
                        var budgetDiv = document.getElementById('turnaroundBudget');
                        if (budgetDiv) {
                            budgetDiv.style.display = this.value === 'turnaround' ? 'block' : 'none';
                        }
                    });
                    crisisSelect._listenerAdded = true;
                }
            }
        }

        validateDecisions(decisions) {
            var period = window.mySimulation.state.currentPeriod;
            this._updateBriefing(window.mySimulation.state);

            if (period === 1) {
                var tariffInput = document.getElementById('tariffInput');
                if (tariffInput) decisions.tariff = parseFloat(tariffInput.value);
                if (!decisions.tariff || decisions.tariff < 10 || decisions.tariff > 40) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('tariff_warning'), 'warning'
                    );
                    return false;
                }
            } else if (period === 2) {
                var modelSelect = document.getElementById('modelSelect');
                if (modelSelect) decisions.model = modelSelect.value;
                var tariffInput2 = document.getElementById('tariffInput2');
                if (tariffInput2) decisions.tariff = parseFloat(tariffInput2.value);
                if (!decisions.tariff || decisions.tariff < 10 || decisions.tariff > 40) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('tariff_warning'), 'warning'
                    );
                    return false;
                }
            } else if (period === 3) {
                var crisisSelect = document.getElementById('crisisSelect');
                if (crisisSelect) decisions.crisisResponse = crisisSelect.value;
                var budgetInput = document.getElementById('budgetInput');
                if (budgetInput) decisions.additionalBudget = parseFloat(budgetInput.value);
            } else if (period === 4) {
                var structureSelect = document.getElementById('structureSelect');
                if (structureSelect) decisions.sustainableStructure = structureSelect.value;
                var finalTariffInput = document.getElementById('finalTariffInput');
                if (finalTariffInput) decisions.finalTariff = parseFloat(finalTariffInput.value);
                if (!decisions.finalTariff || decisions.finalTariff < 5 || decisions.finalTariff > 30) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('tariff_warning_r4'), 'warning'
                    );
                    return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;
            var monthlyRevenue = 0;
            var monthlyCosts = 0;
            var monthlyPL = 0;
            var patientsMonth = 0;
            var analysis = '';

            if (round === 1) {
                var tariff = d.tariff;
                var conversion = this._getConversion(tariff);
                var visitsMonth = Math.round(1800 * conversion);
                var revenue = visitsMonth * tariff;
                var varCostTotal = visitsMonth * 25;
                var fixedCost = 15000;
                var costs = varCostTotal + fixedCost;
                var pl = revenue - costs;
                var margin = tariff - 25;
                var breakeven = margin > 0 ? Math.ceil(15000 / margin) : 99999;

                monthlyRevenue = revenue;
                monthlyCosts = costs;
                monthlyPL = pl;
                patientsMonth = visitsMonth;

                ds.ruralInvestment = 180000;
                ds.currentTariff = tariff;
                ds.projectedVisits = visitsMonth;

                analysis = this._t('analysis_r1', {
                    tariff: tariff,
                    conv: Math.round(conversion * 100),
                    visits: visitsMonth.toLocaleString(),
                    revenue: Math.round(revenue).toLocaleString(),
                    costs: Math.round(costs).toLocaleString(),
                    plColor: (pl >= 0 ? '#2d8659' : '#c0392b'),
                    pl: Math.round(pl).toLocaleString(),
                    breakeven: breakeven.toLocaleString(),
                    gap: (visitsMonth - breakeven).toLocaleString()
                });

            } else if (round === 2) {
                var model = d.model;
                var tariff = d.tariff;
                var conversion = this._getConversion(tariff);
                var demandMonth = Math.round(1800 * conversion);
                var fixedCosts, varCost, maxCapacity, investmentAmount;

                if (model === 'A') {
                    fixedCosts = 15000; varCost = 25; maxCapacity = 3000; investmentAmount = 180000;
                } else if (model === 'B') {
                    fixedCosts = 15000; varCost = 25; maxCapacity = 3000; investmentAmount = 180000;
                } else if (model === 'C') {
                    fixedCosts = 8000; varCost = 12; maxCapacity = 1500; investmentAmount = 80000;
                } else {
                    fixedCosts = 5000; varCost = 12; maxCapacity = 800; investmentAmount = 60000;
                }

                var actualVisits = Math.min(demandMonth, maxCapacity);
                monthlyRevenue = actualVisits * tariff;
                monthlyCosts = actualVisits * varCost + fixedCosts;
                monthlyPL = monthlyRevenue - monthlyCosts;
                patientsMonth = actualVisits;

                ds.ruralInvestment = investmentAmount;
                ds.currentTariff = tariff;
                ds.currentModel = model;
                ds.fixedCosts = fixedCosts;
                ds.varCost = varCost;
                ds.projectedVisits = actualVisits;

                var marginPerVisit = tariff - varCost;
                var beVisits = marginPerVisit > 0 ? Math.ceil(fixedCosts / marginPerVisit) : 99999;
                var beAchievable = actualVisits >= beVisits;
                var monthsToPayback = monthlyPL > 0 ? Math.ceil(investmentAmount / monthlyPL) : -1;

                var beLabel = beAchievable
                    ? '<span style="color:#2d8659;">' + this._t('lbl_achievable') + '</span>'
                    : '<span style="color:#c0392b;">' + this._t('lbl_not_achievable') + '</span>';
                var paybackText = (monthsToPayback > 0)
                    ? this._t('payback_months', { m: monthsToPayback, y: (monthsToPayback / 12).toFixed(1) })
                    : this._t('payback_na');
                analysis = this._t('analysis_r2', {
                    model: model,
                    tariff: tariff,
                    fixedCosts: fixedCosts.toLocaleString(),
                    varCost: varCost,
                    margin: marginPerVisit,
                    maxCapacity: maxCapacity.toLocaleString(),
                    demand: demandMonth,
                    actual: actualVisits,
                    beVisits: beVisits.toLocaleString(),
                    beLabel: beLabel,
                    plColor: (monthlyPL >= 0 ? '#2d8659' : '#c0392b'),
                    pl: Math.round(monthlyPL).toLocaleString(),
                    investment: investmentAmount.toLocaleString(),
                    payback: paybackText
                });

            } else if (round === 3) {
                var crisis = d.crisisResponse;
                var realDemand = 650;
                var fc = ds.fixedCosts || 8000;
                var vc = ds.varCost || 12;
                var sixMonthLoss = 6 * (realDemand * ds.currentTariff - realDemand * vc - fc);
                if (sixMonthLoss > 0) sixMonthLoss = 0;

                if (crisis === 'abandon') {
                    monthlyPL = 0;
                    patientsMonth = 0;
                    monthlyCosts = 0;
                    monthlyRevenue = 0;
                    ds.abandoned = true;
                    analysis = this._t('analysis_r3_abandon', {
                        sunk: ds.ruralInvestment.toLocaleString(),
                        losses: Math.round(Math.abs(sixMonthLoss)).toLocaleString(),
                        total: Math.round(ds.ruralInvestment + Math.abs(sixMonthLoss)).toLocaleString()
                    });

                } else if (crisis === 'turnaround') {
                    var addBudget = (d.additionalBudget || 30) * 1000;
                    ds.ruralInvestment += addBudget;
                    var improvedDemand = Math.round(realDemand * 1.3);
                    var turnaroundTariff = 25;
                    var extraDoctorCost = 800;
                    monthlyRevenue = improvedDemand * turnaroundTariff;
                    monthlyCosts = improvedDemand * vc + fc + extraDoctorCost;
                    monthlyPL = monthlyRevenue - monthlyCosts;
                    patientsMonth = improvedDemand;
                    var payback = monthlyPL > 0 ? Math.ceil(addBudget / monthlyPL) : -1;
                    var totalSunk = ds.ruralInvestment + Math.abs(sixMonthLoss);

                    var paybackTa = (payback > 0) ? this._t('payback_months_simple', { m: payback }) : this._t('payback_neg');
                    analysis = this._t('analysis_r3_turnaround', {
                        budget: addBudget.toLocaleString(),
                        demand: improvedDemand,
                        plColor: (monthlyPL >= 0 ? '#2d8659' : '#c0392b'),
                        pl: Math.round(monthlyPL).toLocaleString(),
                        payback: paybackTa,
                        totalSunk: Math.round(totalSunk).toLocaleString()
                    });

                } else if (crisis === 'social') {
                    var socialTariff = 15;
                    var socialDemand = Math.round(realDemand * 1.4);
                    monthlyRevenue = socialDemand * socialTariff;
                    monthlyCosts = socialDemand * vc + fc;
                    monthlyPL = monthlyRevenue - monthlyCosts;
                    patientsMonth = socialDemand;
                    var annualSubsidy = Math.abs(monthlyPL) * 12;
                    var pctUrban = (annualSubsidy / ds.urbanAnnualProfit * 100).toFixed(1);

                    analysis = this._t('analysis_r3_social', {
                        demand: socialDemand,
                        revenue: Math.round(monthlyRevenue).toLocaleString(),
                        costs: Math.round(monthlyCosts).toLocaleString(),
                        plColor: (monthlyPL >= 0 ? '#2d8659' : '#c0392b'),
                        pl: Math.round(monthlyPL).toLocaleString(),
                        subsidy: Math.round(annualSubsidy).toLocaleString(),
                        pct: pctUrban
                    });

                } else {
                    var partnerDemand = Math.round(realDemand * 1.1);
                    monthlyRevenue = partnerDemand * 20;
                    monthlyCosts = partnerDemand * 8 + 3000;
                    monthlyPL = monthlyRevenue - monthlyCosts;
                    patientsMonth = partnerDemand;

                    analysis = this._t('analysis_r3_partner', {
                        vc: vc,
                        fc: fc.toLocaleString(),
                        demand: partnerDemand,
                        plColor: (monthlyPL >= 0 ? '#2d8659' : '#c0392b'),
                        pl: Math.round(monthlyPL).toLocaleString()
                    });
                }

            } else if (round === 4) {
                var structure = d.sustainableStructure;
                var finalTariff = d.finalTariff || 15;
                var fc = ds.fixedCosts || 8000;
                var vc = ds.varCost || 12;
                var baseDemand, externalFunding, structureName, structureDetail;

                if (ds.abandoned) {
                    fc = 8000;
                    vc = 12;
                }

                // v1.2.0: the patient tariff moves demand, as in Rounds 1 and 2. Each structure
                // reaches its stated volume at US$15 or less; above that, visits fall with the
                // same conversion curve (25/70 of the volume at US$30).
                var accessFactor = Math.min(1, this._getConversion(finalTariff) / this._getConversion(15));

                if (structure === 'community') {
                    var enrolled = Math.round(12000 * 0.80);
                    var premium = 7;
                    externalFunding = Math.round(enrolled * premium * 0.08);
                    baseDemand = Math.round(900 * accessFactor);
                    structureName = this._t('struct_name_community');
                    structureDetail = this._t('struct_detail_community', { enrolled: enrolled.toLocaleString(), premium: premium, funding: externalFunding.toLocaleString() });
                } else if (structure === 'gov_subsidy') {
                    var govPerVisit = 15;
                    baseDemand = Math.round(700 * accessFactor);
                    externalFunding = baseDemand * govPerVisit;
                    structureName = this._t('struct_name_gov');
                    structureDetail = this._t('struct_detail_gov', { gov: govPerVisit, copay: finalTariff, total: (govPerVisit + finalTariff) });
                } else if (structure === 'ppp') {
                    externalFunding = 4000;
                    baseDemand = Math.round(600 * accessFactor);
                    fc = Math.round(fc * 0.6);
                    structureName = this._t('struct_name_ppp');
                    structureDetail = this._t('struct_detail_ppp', { funding: externalFunding.toLocaleString(), fc: fc.toLocaleString() });
                } else {
                    var crossSubsidy = Math.round(ds.urbanAnnualProfit * 0.05 / 12);
                    externalFunding = crossSubsidy;
                    baseDemand = Math.round(500 * accessFactor);
                    structureName = this._t('struct_name_cross');
                    structureDetail = this._t('struct_detail_cross', { cross: crossSubsidy.toLocaleString() });
                }

                monthlyRevenue = baseDemand * finalTariff + externalFunding;
                monthlyCosts = baseDemand * vc + fc;
                monthlyPL = monthlyRevenue - monthlyCosts;
                patientsMonth = baseDemand;
                var annualPatients = patientsMonth * 12;
                var coveragePct = Math.round(patientsMonth / 12000 * 12 / 1.8 * 100);
                if (coveragePct > 100) coveragePct = 100;

                var sustainLabel = (monthlyPL >= 0)
                    ? '<span style="color:#2d8659;font-weight:700;">' + this._t('lbl_viable') + '</span>'
                    : this._t('lbl_needs_subsidy', { amt: Math.abs(Math.round(monthlyPL)).toLocaleString() });
                analysis = this._t('analysis_r4', {
                    structureName: structureName,
                    structureDetail: structureDetail,
                    finalTariff: finalTariff,
                    funding: Math.round(externalFunding).toLocaleString(),
                    demand: baseDemand,
                    floor: this.ACCESS_FLOOR,
                    access: this._t(baseDemand >= this.ACCESS_FLOOR ? 'lbl_access_met' : 'lbl_access_short'),
                    annual: annualPatients.toLocaleString(),
                    revenue: Math.round(monthlyRevenue).toLocaleString(),
                    costs: Math.round(monthlyCosts).toLocaleString(),
                    plColor: (monthlyPL >= 0 ? '#2d8659' : '#c0392b'),
                    pl: Math.round(monthlyPL).toLocaleString(),
                    coverage: coveragePct,
                    sustain: sustainLabel
                });
            }

            ds.monthlyPL = Math.round(monthlyPL);
            ds.patientsServed = patientsMonth;
            ds.lastAnalysis = analysis;
            ds.plHistory.push(Math.round(monthlyPL));
            ds.investmentHistory.push(ds.ruralInvestment);
            ds.patientsHistory.push(patientsMonth);

            // --- GRADING CONTRACT: server reads domainState.performance.overallScore ---
            var composite = this._composite(ds);
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = composite;
            ds.performance.grade = this._grade(composite);
            ds.performance.tier = this._tier(composite);
            ds.performanceTier = this._tier(composite);

            var self = this;
            // Guard: don't re-brief past the final round (avoids a phantom Round 5 briefing).
            if (round < (state.maxPeriods || this.ROUNDS.length)) {
                setTimeout(((__eqilNext) => function() {
                    self._updateBriefing({ currentPeriod: __eqilNext, domainState: ds });
                })(state.currentPeriod + 1), 500);
            }

            return {
                period: round,
                monthlyRevenue: Math.round(monthlyRevenue),
                monthlyCosts: Math.round(monthlyCosts),
                monthlyPL: Math.round(monthlyPL),
                patientsMonth: patientsMonth,
                investment: ds.ruralInvestment,
                overallScore: composite
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('urbanProfitDisplay', 'domainState.urbanAnnualProfit',
                function(v) { return '$' + Math.round(v).toLocaleString(); });
            uiManager.bind('monthlyPLDisplay', 'domainState.monthlyPL',
                function(v) { return '$' + Math.round(v).toLocaleString(); });
            uiManager.bind('investmentDisplay', 'domainState.ruralInvestment',
                function(v) { return '$' + Math.round(v).toLocaleString(); });
            uiManager.bind('patientsDisplay', 'domainState.patientsServed');
        }

        getChartConfig() {
            return {
                plChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Monthly P&L ($)',
                            data: [],
                            backgroundColor: 'rgba(13,115,119,0.6)',
                            borderColor: '#0d7377',
                            borderWidth: 2,
                            borderRadius: 6
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: {
                                display: true,
                                text: 'Rural Clinic Monthly P&L by Round',
                                color: '#1a2d5e',
                                font: { size: 14, weight: '600' },
                                padding: { bottom: 16 }
                            },
                            legend: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: false,
                                grid: { color: 'rgba(0,0,0,0.06)' },
                                ticks: {
                                    callback: function(v) { return '$' + v.toLocaleString(); },
                                    color: '#7f8c9b'
                                }
                            },
                            x: {
                                grid: { display: false },
                                ticks: { color: '#7f8c9b' }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var roundNames = ['R1: Market', 'R2: Model', 'R3: Crisis', 'R4: Structure'];
            var labels = state.domainState.plHistory.map(function(_, i) { return roundNames[i] || 'R' + (i + 1); });
            var bgColors = state.domainState.plHistory.map(function(v) {
                return v >= 0 ? 'rgba(45,134,89,0.65)' : 'rgba(192,57,43,0.65)';
            });
            var borderColors = state.domainState.plHistory.map(function(v) {
                return v >= 0 ? '#2d8659' : '#c0392b';
            });
            return {
                plChart: {
                    labels: labels,
                    datasets: [{
                        data: state.domainState.plHistory,
                        backgroundColor: bgColors,
                        borderColor: borderColors
                    }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastResult = history[history.length - 1].results || {};
            var finalPL = lastResult.monthlyPL || 0;
            var totalPatients = 0;
            var totalInvested = 0;
            for (var i = 0; i < history.length; i++) {
                var r = history[i].results || {};
                totalPatients += (r.patientsMonth || 0);
                if (r.investment) totalInvested = r.investment;
            }
            // Same P&L thresholds as v1.0.0 plus the v1.2.0 access floor, 0-3 rescaled to 0-100.
            var finalPatients = lastResult.patientsMonth || 0;
            var scoreIdx = this._idxFrom(finalPL, finalPatients, totalPatients);
            var lowAccess = this._lowAccess(finalPL, finalPatients);
            var overall = this._cl(Math.round(scoreIdx / 3 * 100));
            var gradeKey = lowAccess ? 'grade_low_access' : this._gradeKey(scoreIdx);
            var insights = [];
            if (lowAccess) {
                insights.push(this._t('insight_access_1', { patients: finalPatients.toLocaleString(), floor: this.ACCESS_FLOOR }));
                insights.push(this._t('insight_access_2'));
            } else if (scoreIdx === 3) {
                insights.push(this._t('insight_sus_1'));
                insights.push(this._t('insight_sus_2'));
            } else if (scoreIdx === 2) {
                insights.push(this._t('insight_sub_1'));
                insights.push(this._t('insight_sub_2'));
            } else if (scoreIdx === 1) {
                insights.push(this._t('insight_uns_1'));
                insights.push(this._t('insight_uns_2'));
            } else {
                insights.push(this._t('insight_wd_1'));
                insights.push(this._t('insight_wd_2', { invested: totalInvested.toLocaleString() }));
            }
            if (totalPatients > 1500) {
                insights.push(this._t('insight_impact', { patients: totalPatients.toLocaleString() }));
            }
            return {
                overallScore: overall,
                score: overall,
                rawScore: scoreIdx,
                grade: this._grade(overall),
                tier: this._tier(overall),
                performance: gradeKey,
                performanceLabel: this._t(gradeKey),
                finalMonthlyPL: finalPL,
                totalInvested: totalInvested,
                totalPatientVisits: totalPatients,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var T = this._t.bind(this);
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            var verdict = s.performanceLabel || (s.performance ? this._t(s.performance) : '');
            var pl = (typeof s.finalMonthlyPL === 'number') ? s.finalMonthlyPL : 0;
            var plColor = pl >= 0 ? '#2d8659' : '#c0392b';
            var kpis = ''
                + '<div class="clinica-cm-kpi"><span>' + T('cm_kpi_pl') + '</span><b style="color:' + plColor + ';">' + this._money(pl) + '</b></div>'
                + '<div class="clinica-cm-kpi"><span>' + T('cm_kpi_patients') + '</span><b>' + (s.totalPatientVisits || 0).toLocaleString() + '</b></div>'
                + '<div class="clinica-cm-kpi"><span>' + T('cm_kpi_invested') + '</span><b>' + this._money(s.totalInvested || 0) + '</b></div>';
            var items = (s.insights || []).map(function(x) { return '<li>' + x + '</li>'; }).join('');
            return '<div class="clinica-cm">'
                + '<div class="clinica-cm-score">' + score + '<span class="clinica-cm-max">/100</span></div>'
                + '<div class="clinica-cm-verdict">' + verdict + '</div>'
                + '<div class="clinica-cm-debrief">' + T('cm_debrief') + '</div>'
                + '<div class="clinica-cm-kpis">' + kpis + '</div>'
                + '<ul class="clinica-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            var round = state.currentPeriod;
            if (round === 1) {
                if (results.monthlyPL < -10000) {
                    return window.mySimulation.t('hint_breakeven_impossible');
                }
                return window.mySimulation.t('hint_round1_done');
            }
            if (round === 2) {
                var margin = state.decisions.tariff - state.domainState.varCost;
                if (margin <= 0) return window.mySimulation.t('hint_negative_margin');
                if (results.patientsMonth < 500) return window.mySimulation.t('hint_low_demand');
                return null;
            }
            if (round === 3) {
                return window.mySimulation.t('hint_sunk_cost');
            }
            if (round === 4) {
                if (this._lowAccess(results.monthlyPL, results.patientsMonth || 0)) return window.mySimulation.t('hint_low_access');
                if (results.monthlyPL >= 0) return window.mySimulation.t('hint_sustainable');
                return window.mySimulation.t('hint_needs_subsidy');
            }
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.monthlyRevenue', label: 'Revenue', i18nKey: 'col_revenue', formatter: function(v) { return '$' + (v || 0).toLocaleString(); } },
